import json,hashlib,pathlib,datetime
root=pathlib.Path.cwd();products=json.loads((root/'src/data/catalogue.json').read_text(encoding='utf-8'))
chosen=[]
for p in products[::6]+[p for p in products if 'bed' in p['subcategory'].lower() or 'sofa' in p['subcategory'].lower()][:45]:
 if p['id'] not in {x['id'] for x in chosen}:chosen.append(p)
comments=[('Thoughtful proportions','The proportions and clean lines are appealing for a compact room.'),('A versatile finish','The pictured finish would work well with neutral walls and natural textures.'),('Useful storage','The storage layout looks practical. I would check the internal space before choosing it.'),('Check the measurements','The design is attractive, but the listed size needs careful checking against the room.'),('A strong design option','This is one of the more balanced designs in the collection for the displayed price.'),('Not my preferred style','The shape feels a little too minimal for my taste; I would prefer a softer profile.'),('Good material combination','The material and colour combination would pair well with similar pieces in the room.'),('Consider the room layout','I would leave extra clearance around this piece so the room stays easy to move through.'),('A calm, simple look','The restrained shape makes this an easy starting point for a coordinated room.'),('More finish choices needed','The design is interesting, although I would like to compare more finish options.')]
ratings=[5,4,4,5,3,4,5,2,4,5,3,4,1,5,4,5,4]
reviews=[]
for i in range(312):
 p=chosen[(i*17+i//9)%len(chosen)];headline,body=comments[(i*7+i//11)%len(comments)];key=hashlib.sha256(f'sample-review:{i}:{p["id"]}'.encode()).hexdigest();rid=f'{key[:8]}-{key[8:12]}-4{key[13:16]}-a{key[17:20]}-{key[20:32]}'
 reviews.append({'id':rid,'product_slug':p['id'],'rating':ratings[(i*3+i//13)%len(ratings)],'headline':headline,'comment':body,'author_label':f'Sample reviewer {i+1:03}','created_at':(datetime.datetime(2026,8,1,12,tzinfo=datetime.timezone.utc)+datetime.timedelta(days=i%85)).isoformat(),'is_sample':True})
(root/'src/data/sample-reviews.json').write_text(json.dumps(reviews,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def q(s):return "'"+str(s).replace("'","''")+"'"
sql='begin;\ncreate table public.catalogue_reviews (\n id uuid primary key,product_slug text not null references public.products(slug),rating integer not null check(rating between 1 and 5),headline text not null check(length(headline) between 1 and 120),comment text not null check(length(comment) between 1 and 1200),author_label text not null,created_at timestamptz not null,is_sample boolean not null default true check(is_sample)\n);\nalter table public.catalogue_reviews enable row level security;\nrevoke all on public.catalogue_reviews from public,anon,authenticated;\ngrant select on public.catalogue_reviews to anon,authenticated;\ncreate policy published_sample_reviews on public.catalogue_reviews for select to anon,authenticated using(is_sample and exists(select 1 from public.products p where p.slug=product_slug and p.active));\ncreate index catalogue_reviews_product_created on public.catalogue_reviews(product_slug,created_at desc);\n'
for r in reviews:sql+='insert into public.catalogue_reviews(id,product_slug,rating,headline,comment,author_label,created_at,is_sample) values('+','.join(q(r[k]) if k not in ['rating','is_sample'] else str(r[k]).lower() for k in ['id','product_slug','rating','headline','comment','author_label','created_at','is_sample'])+') on conflict(id) do nothing;\n'
sql+='commit;\n';(root/'supabase/migrations/202610250007_sample_reviews.sql').write_text(sql,encoding='utf-8');print('Prepared',len(reviews),'sample reviews for',len(set(r['product_slug'] for r in reviews)),'products')
